package mz.bam.seeky.android;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.apache.commons.compress.archivers.tar.*;import org.apache.commons.compress.archivers.zip.*;import org.apache.commons.compress.archivers.sevenz.*;import org.apache.commons.compress.compressors.*;import org.junit.*;import static org.junit.Assert.*;
public class Archive5170Test {
 File root,out;final ArchiveFiles.Progress progress=(n,b,c)->{};
 @Before public void setup()throws Exception{root=Files.createTempDirectory("seeky-archive-test").toFile();out=new File(root,"out");assertTrue(out.mkdir());}
 @After public void close(){ArchiveFiles.remove(root);}
 File text(String name,String value)throws Exception{File f=new File(root,name);if(f.getParentFile()!=null)f.getParentFile().mkdirs();Files.write(f.toPath(),value.getBytes("UTF-8"));return f;}
 String read(File f)throws Exception{return new String(Files.readAllBytes(f.toPath()),"UTF-8");}
 void failExtract(File source)throws Exception{try{ArchiveFiles.extract(source,out,"result",null,()->false,progress);fail("Expected rejection");}catch(IOException expected){}assertEquals(0,out.list().length);}
 File zip(String entry,String data)throws Exception{File f=new File(root,"input.zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(f))){z.putNextEntry(new ZipEntry(entry));z.write(data.getBytes("UTF-8"));z.closeEntry();}return f;}
 @Test public void zipRoundTripPreservesUnicodeEmptyFoldersAndOriginals()throws Exception{File folder=new File(root,"Livros");assertTrue(new File(folder,"vazia").mkdirs());text("Livros/Isaías.txt","Capítulo 5 · versículo 6");File zip=ArchiveFiles.compress(Collections.singletonList(folder),out,"livros.zip",()->false,progress);File restored=ArchiveFiles.extract(zip,out,"restore",null,()->false,progress);assertEquals("Capítulo 5 · versículo 6",read(new File(restored,"Livros/Isaías.txt")));assertTrue(new File(restored,"Livros/vazia").isDirectory());assertTrue(new File(folder,"Isaías.txt").isFile());}
 @Test public void traversalIsRejectedAndStagingIsRemoved()throws Exception{failExtract(zip("../escape.txt","bad"));assertFalse(new File(root,"escape.txt").exists());}
 @Test public void windowsAbsolutePathIsRejected()throws Exception{failExtract(zip("C:\\Windows\\bad","bad"));}
 @Test public void repeatedArchiveEntriesAreNotOverwritten()throws Exception{File f=new File(root,"duplicate.zip");try(ZipArchiveOutputStream z=new ZipArchiveOutputStream(f)){for(int i=0;i<2;i++){z.putArchiveEntry(new ZipArchiveEntry("same.txt"));z.write(i);z.closeArchiveEntry();}}failExtract(f);}
 @Test public void tarSymlinksAreRejected()throws Exception{File f=new File(root,"link.tar");try(TarArchiveOutputStream z=new TarArchiveOutputStream(new FileOutputStream(f))){TarArchiveEntry e=new TarArchiveEntry("link",TarConstants.LF_SYMLINK);e.setLinkName("../outside");z.putArchiveEntry(e);z.closeArchiveEntry();}failExtract(f);}
 @Test public void cancellationRemovesPartialZipAndKeepsSources()throws Exception{File input=text("original.txt","Keep this");try{ArchiveFiles.compress(Collections.singletonList(input),out,"cancel.zip",()->true,progress);fail();}catch(InterruptedIOException expected){}assertEquals(0,out.list().length);assertEquals("Keep this",read(input));}
 @Test public void existingTargetsAreNeverOverwritten()throws Exception{File original=new File(out,"keep.zip");Files.write(original.toPath(),new byte[]{1,2,3});try{ArchiveFiles.compress(Collections.singletonList(text("a.txt","a")),out,"keep.zip",()->false,progress);fail();}catch(IOException expected){}assertArrayEquals(new byte[]{1,2,3},Files.readAllBytes(original.toPath()));}
 @Test public void compressionInsideTheSourceFolderIsRejected()throws Exception{File folder=new File(root,"folder");folder.mkdir();try{ArchiveFiles.compress(Collections.singletonList(folder),folder,"inside.zip",()->false,progress);fail();}catch(IOException expected){}assertEquals(0,folder.list().length);}
 byte[] tar()throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(TarArchiveOutputStream t=new TarArchiveOutputStream(bytes)){byte[] data="A matéria".getBytes("UTF-8");TarArchiveEntry entry=new TarArchiveEntry("pasta/matéria.txt");entry.setSize(data.length);t.putArchiveEntry(entry);t.write(data);t.closeArchiveEntry();}return bytes.toByteArray();}
 @Test public void tarGzipBzip2AndXzExtractRealContent()throws Exception{for(String type:new String[]{"gz","bzip2","xz"}){String suffix=type.equals("bzip2")?"bz2":type;File source=new File(root,"input.tar."+suffix);try(OutputStream z=new CompressorStreamFactory().createCompressorOutputStream(type,new FileOutputStream(source))){z.write(tar());}File dir=ArchiveFiles.extract(source,out,"tar-"+suffix,null,()->false,progress);assertEquals("A matéria",read(new File(dir,"pasta/matéria.txt")));}}
 @Test public void singleCompressedStreamsKeepTheirOriginalBaseName()throws Exception{for(String type:new String[]{"gz","bzip2","xz"}){String suffix=type.equals("bzip2")?"bz2":type;File source=new File(root,"texto.txt."+suffix);try(OutputStream z=new CompressorStreamFactory().createCompressorOutputStream(type,new FileOutputStream(source))){z.write("Olá".getBytes("UTF-8"));}File dir=ArchiveFiles.extract(source,out,"single-"+suffix,null,()->false,progress);assertEquals("Olá",read(new File(dir,"texto.txt")));}}
 @Test public void sevenZipWithLzma2IsDecoded()throws Exception{File source=new File(root,"input.7z"),text=text("original.txt","Sete arquivos · texto");try(SevenZOutputFile seven=new SevenZOutputFile(source)){org.tukaani.xz.LZMA2Options options=new org.tukaani.xz.LZMA2Options();options.setDictSize(1048576);seven.setContentMethods(Collections.singletonList(new SevenZMethodConfiguration(SevenZMethod.LZMA2,options)));seven.putArchiveEntry(seven.createArchiveEntry(text,"documento.txt"));seven.write(Files.readAllBytes(text.toPath()));seven.closeArchiveEntry();}File dir=ArchiveFiles.extract(source,out,"seven",null,()->false,progress);assertEquals("Sete arquivos · texto",read(new File(dir,"documento.txt")));}
 @Test public void corruptedStoredZipFailsCrcAndPublishesNothing()throws Exception{byte[] data="UNIQUE_PAYLOAD".getBytes("UTF-8");CRC32 crc=new CRC32();crc.update(data);File f=new File(root,"corrupt.zip");try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(f))){ZipEntry e=new ZipEntry("a.txt");e.setMethod(ZipEntry.STORED);e.setSize(data.length);e.setCompressedSize(data.length);e.setCrc(crc.getValue());zip.putNextEntry(e);zip.write(data);zip.closeEntry();}byte[] bytes=Files.readAllBytes(f.toPath());int offset=new String(bytes,"ISO-8859-1").indexOf("UNIQUE_PAYLOAD");assertTrue(offset>0);bytes[offset]^=1;Files.write(f.toPath(),bytes);failExtract(f);}
 @Test public void badZipHeaderDoesNotCreateAnEmptySuccessFolder()throws Exception{File f=new File(root,"broken.zip");Files.write(f.toPath(),new byte[]{'P','K',3,4,1,2});failExtract(f);}
 @Test public void symlinkSourcesAreNotFollowed()throws Exception{File original=text("secret.txt","Original");File link=new File(root,"link");Files.createSymbolicLink(link.toPath(),original.toPath());try{ArchiveFiles.compress(Collections.singletonList(link),out,"links.zip",()->false,progress);fail();}catch(IOException expected){}assertEquals(0,out.list().length);assertEquals("Original",read(original));Files.delete(link.toPath());}
 @Test public void emptyZipRemainsAValidArchive()throws Exception{File f=new File(root,"empty.zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(f))){}assertTrue(ArchiveFiles.extract(f,out,"empty",null,()->false,progress).isDirectory());}
 @Test public void unsupportedRarReturnsAnExplicitFailureWithoutPartialFiles()throws Exception{failExtract(text("input.rar","RAR"));}
 @Test public void deflatedZipDataDescriptorCrcIsAlsoVerified()throws Exception{File source=zip("texto.txt","Um texto que mantém a sua integridade.");byte[] bytes=Files.readAllBytes(source.toPath());int found=-1;for(int i=0;i<bytes.length-8;i++)if(bytes[i]==0x50&&bytes[i+1]==0x4b&&bytes[i+2]==7&&bytes[i+3]==8){found=i+4;break;}assertTrue(found>0);bytes[found]^=1;Files.write(source.toPath(),bytes);failExtract(source);}

}
